import React, { useState } from 'react';
import { 
  Bot, 
  Play, 
  Pause, 
  Square, 
  Settings,
  Activity,
  FileText,
  Clock,
  AlertCircle,
  CheckCircle
} from 'lucide-react';
import { useBot } from '../contexts/BotContext';

const BotControl = () => {
  const { 
    botStatus, 
    startBot, 
    stopBot, 
    pauseBot,
    currentFolder,
    processedFiles,
    totalFiles,
    realTimeUpdates
  } = useBot();

  const [selectedFolder, setSelectedFolder] = useState('');
  const [autoRestart, setAutoRestart] = useState(false);
  const [maxRetries, setMaxRetries] = useState(3);

  const handleStartBot = () => {
    if (selectedFolder) {
      startBot();
    } else {
      alert('กรุณาเลือกโฟลเดอร์ที่ต้องการประมวลผล');
    }
  };

  const getStatusIcon = (status) => {
    switch (status) {
      case 'running':
        return <Activity className="w-6 h-6 text-success-600 animate-pulse" />;
      case 'paused':
        return <Pause className="w-6 h-6 text-warning-600" />;
      case 'error':
        return <AlertCircle className="w-6 h-6 text-error-600" />;
      default:
        return <Square className="w-6 h-6 text-gray-600" />;
    }
  };

  const getStatusText = (status) => {
    switch (status) {
      case 'running':
        return 'กำลังทำงาน';
      case 'paused':
        return 'หยุดชั่วคราว';
      case 'error':
        return 'เกิดข้อผิดพลาด';
      default:
        return 'หยุดทำงาน';
    }
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'running':
        return 'bg-success-100 text-success-800';
      case 'paused':
        return 'bg-warning-100 text-warning-800';
      case 'error':
        return 'bg-error-100 text-error-800';
      default:
        return 'bg-gray-100 text-gray-800';
    }
  };

  return (
    <div className="p-6">
      {/* Header */}
      <div className="mb-8">
        <h1 className="text-3xl font-bold text-gray-900 mb-2">ควบคุมบอท</h1>
        <p className="text-gray-600">จัดการการทำงานของระบบบอทอัตโนมัติ</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Bot Status */}
        <div className="lg:col-span-2">
          <div className="card">
            <div className="flex items-center justify-between mb-6">
              <h2 className="text-xl font-semibold text-gray-900">สถานะบอท</h2>
              <div className={`status-badge ${getStatusColor(botStatus)}`}>
                {getStatusIcon(botStatus)}
                <span className="ml-2">{getStatusText(botStatus)}</span>
              </div>
            </div>

            {/* Progress Section */}
            {totalFiles > 0 && (
              <div className="mb-6">
                <div className="flex items-center justify-between mb-2">
                  <span className="text-sm font-medium text-gray-700">ความคืบหน้า</span>
                  <span className="text-sm text-gray-500">
                    {processedFiles} จาก {totalFiles} ไฟล์
                  </span>
                </div>
                <div className="w-full bg-gray-200 rounded-full h-3">
                  <div 
                    className="bg-primary-600 h-3 rounded-full transition-all duration-300"
                    style={{ width: `${(processedFiles / totalFiles) * 100}%` }}
                  ></div>
                </div>
                <p className="text-sm text-gray-600 mt-2">
                  {realTimeUpdates.currentAction || 'รอการเริ่มต้น...'}
                </p>
              </div>
            )}

            {/* Control Buttons */}
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
              <button
                onClick={handleStartBot}
                disabled={botStatus === 'running'}
                className="btn-success disabled:opacity-50 disabled:cursor-not-allowed"
              >
                <Play className="w-4 h-4 mr-2" />
                เริ่มการทำงาน
              </button>
              
              <button
                onClick={pauseBot}
                disabled={botStatus !== 'running'}
                className="btn-warning disabled:opacity-50 disabled:cursor-not-allowed"
              >
                <Pause className="w-4 h-4 mr-2" />
                หยุดชั่วคราว
              </button>
              
              <button
                onClick={stopBot}
                disabled={botStatus === 'stopped'}
                className="btn-error disabled:opacity-50 disabled:cursor-not-allowed"
              >
                <Square className="w-4 h-4 mr-2" />
                หยุดการทำงาน
              </button>
            </div>
          </div>
        </div>

        {/* Configuration */}
        <div className="card">
          <h2 className="text-xl font-semibold text-gray-900 mb-4">การตั้งค่า</h2>
          
          <div className="space-y-4">
            {/* Folder Selection */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                โฟลเดอร์ที่ต้องการประมวลผล
              </label>
              <select
                value={selectedFolder}
                onChange={(e) => setSelectedFolder(e.target.value)}
                className="input-field"
              >
                <option value="">เลือกโฟลเดอร์</option>
                <option value="A">A.โฟลเดอร์หลัก</option>
                <option value="AA">AA.โฟลเดอร์หลัก</option>
                <option value="AAA">AAA.โฟลเดอร์หลัก</option>
              </select>
            </div>

            {/* Auto Restart */}
            <div className="flex items-center">
              <input
                type="checkbox"
                id="autoRestart"
                checked={autoRestart}
                onChange={(e) => setAutoRestart(e.target.checked)}
                className="w-4 h-4 text-primary-600 border-gray-300 rounded focus:ring-primary-500"
              />
              <label htmlFor="autoRestart" className="ml-2 text-sm text-gray-700">
                รีสตาร์ทอัตโนมัติเมื่อเกิดข้อผิดพลาด
              </label>
            </div>

            {/* Max Retries */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                จำนวนครั้งสูงสุดในการลองใหม่
              </label>
              <input
                type="number"
                min="1"
                max="10"
                value={maxRetries}
                onChange={(e) => setMaxRetries(parseInt(e.target.value))}
                className="input-field"
              />
            </div>
          </div>
        </div>
      </div>

      {/* Current Activity */}
      <div className="card mt-6">
        <h2 className="text-xl font-semibold text-gray-900 mb-4">กิจกรรมปัจจุบัน</h2>
        
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
          <div className="flex items-center space-x-3 p-3 bg-gray-50 rounded-lg">
            <FileText className="w-5 h-5 text-primary-600" />
            <div>
              <p className="text-sm font-medium text-gray-900">โฟลเดอร์ปัจจุบัน</p>
              <p className="text-sm text-gray-600">{currentFolder || 'ไม่มีข้อมูล'}</p>
            </div>
          </div>

          <div className="flex items-center space-x-3 p-3 bg-gray-50 rounded-lg">
            <Clock className="w-5 h-5 text-warning-600" />
            <div>
              <p className="text-sm font-medium text-gray-900">เวลาที่ใช้</p>
              <p className="text-sm text-gray-600">00:00:00</p>
            </div>
          </div>

          <div className="flex items-center space-x-3 p-3 bg-gray-50 rounded-lg">
            <CheckCircle className="w-5 h-5 text-success-600" />
            <div>
              <p className="text-sm font-medium text-gray-900">ไฟล์ที่สำเร็จ</p>
              <p className="text-sm text-gray-600">{processedFiles}</p>
            </div>
          </div>

          <div className="flex items-center space-x-3 p-3 bg-gray-50 rounded-lg">
            <AlertCircle className="w-5 h-5 text-error-600" />
            <div>
              <p className="text-sm font-medium text-gray-900">ไฟล์ที่ล้มเหลว</p>
              <p className="text-sm text-gray-600">0</p>
            </div>
          </div>
        </div>
      </div>

      {/* Log Preview */}
      <div className="card mt-6">
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-xl font-semibold text-gray-900">บันทึกการทำงานล่าสุด</h2>
          <button className="text-sm text-primary-600 hover:text-primary-700">
            ดูบันทึกทั้งหมด
          </button>
        </div>
        
        <div className="space-y-2">
          <div className="flex items-center space-x-3 p-2 bg-gray-50 rounded">
            <div className="w-2 h-2 bg-success-500 rounded-full"></div>
            <span className="text-sm text-gray-600">บอทเริ่มการทำงาน</span>
            <span className="text-xs text-gray-500 ml-auto">12:30:15</span>
          </div>
          <div className="flex items-center space-x-3 p-2 bg-gray-50 rounded">
            <div className="w-2 h-2 bg-primary-500 rounded-full"></div>
            <span className="text-sm text-gray-600">กำลังประมวลผลไฟล์ PDF</span>
            <span className="text-xs text-gray-500 ml-auto">12:30:20</span>
          </div>
          <div className="flex items-center space-x-3 p-2 bg-gray-50 rounded">
            <div className="w-2 h-2 bg-warning-500 rounded-full"></div>
            <span className="text-sm text-gray-600">พบไฟล์ที่ไม่สามารถประมวลผลได้</span>
            <span className="text-xs text-gray-500 ml-auto">12:30:25</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default BotControl;
